import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    # connected components of 2s; for each component, if it encloses area (bounding box interior zeros), fill interior zeros with 8
    from collections import deque
    seen=[[False]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]==2 and not seen[i][j]:
                comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==2 and not seen[ny][nx]:
                            seen[ny][nx]=True; q.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                # a closed rectangle ring: comp size == perimeter of bbox
                per=2*(y1-y0)+2*(x1-x0) if y1>y0 and x1>x0 else 0
                if y1-y0>=2 and x1-x0>=2 and len(comp)==per:
                    for y in range(y0+1,y1):
                        for x in range(x0+1,x1):
                            if g[y][x]==0:
                                out[y][x]=8
    return out

